// ---- recipe alias: wo naam jo themealdb par nahi milte ----
global.__X5_RECIPE_ALIAS = {
  bagel:'bread', bibimbap:'rice', bulgogi:'beef', enchiladas:'enchilada', friedrice:'fried rice',
  kimchi:'fermented', miso:'soup', nigiri:'sushi', okra:'bhindi', padthai:'pad thai',
  sushiroll:'sushi', suop:'soup', tiramisu:'cake', vindaloo:'curry', tikkamasala:'tandoori',
};


exports.commands = Object.keys(DESC5).map(name => ({
  name,
  desc: DESC5[name],
  category: CATOF5[name],
  handler: async (m, sock) => {
    try {
      const r = await dispatch5(m, sock, name.toLowerCase());
      if (r === null || r === undefined) return '✔ .' + name + ' — jawab bhej diya.';
      return r;
    } catch (e) {
      return '⚠️ ' + name + ': ' + (e.message || 'masla hua') + ' — dobara koshish karo.';
    }
  }
}));
